const assert=require('node:assert/strict');const api=require('./scoreboard-mutation-v2.js');const d=new Map();const storage={getItem:k=>d.get(k)||null,setItem:(k,v)=>d.set(k,v)};const s=api.createStore(storage);const m=s.createMutation('u1',{mutationId:'m1',entityType:'record',operation:'add',payload:{points:5}});assert.equal(m.status,'PENDING');assert.equal(s.createMutation('u1',{mutationId:'m1',entityType:'record',operation:'add',payload:{points:5}}).sequence,m.sequence);assert.throws(()=>s.createMutation('u1',{mutationId:'m1',entityType:'record',operation:'add',payload:{points:6}}),/different payload/);assert.equal(s.getPending('u2').length,0);s.markUnknown('u1','m1');assert.equal(s.read('u1').mutations[0].status,'UNKNOWN');s.acknowledge('u1',['m1']);assert.equal(s.read('u1').mutations[0].status,'ACKNOWLEDGED');s.createMutation('u1',{mutationId:'m2',entityType:'record',operation:'add',payload:{points:1}});s.startReset('u1','reset-1');s.startReset('u1','reset-1');s.confirmReset('u1','reset-1');assert.equal(s.read('u1').epoch,1);assert.equal(s.read('u1').mutations.find(x=>x.mutationId==='m2').status,'RECOVERY_REQUIRED');console.log('Scoreboard V2 foundation tests: PASS');